308.             { id: "typescript", label: "TypeScript", correct: true }
309.           ]
310.         }
311.       ];
312. 
313.       const escapeHtml = (value) =>
314.         String(value)
315.           .replaceAll("&", "&amp;")
316.           .replaceAll("<", "&lt;")
317.           .replaceAll(">", "&gt;")
318.           .replaceAll('"', "&quot;")
