   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div id="app"></div>
     </main>

     <script>
       const quizData = [
         {
           id: "languages",
           prompt: "Which of these are programming languages?",
           helpText: "Select every option that is a language used to write computer programs.",
           choices: [
             { id: "python", label: "Python", correct: true },
             { id: "html", label: "HTML", correct: false },
             { id: "ruby", label: "Ruby", correct: true },
             { id: "wifi", label: "Wi-Fi", correct: false }
           ]
         },
         {
           id: "compiled",
           prompt: "Which languages are commonly compiled before running?",
           choices: [
             { id: "c", label: "C", correct: true },
             { id: "rust", label: "Rust", correct: true },
             { id: "english", label: "English", correct: false },
             { id: "go", label: "Go", correct: true }
           ]
         },
         {
           id: "web",
           prompt: "Which languages are often used for web development?",
           choices: [
             { id: "javascript", label: "JavaScript", correct: true },
             { id: "php", label: "PHP", correct: true },
             { id: "css", label: "CSS", correct: false },
             { id: "typescript", label: "TypeScript", correct: true }
           ]
         }
       ];

       const escapeHtml = (value) =>
         String(value)
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#039;");

       const Choice = ({ questionId, choice }) => {
         const inputId = `${questionId}-${choice.id}`;
         return `
           <div class="choice">
             <input id="${inputId}" name="${questionId}" type="checkbox" value="${escapeHtml(choice.id)}">
             <label for="${inputId}">${escapeHtml(choice.label)}</label>
           </div>
         `;
       };

       const QuestionGroup = ({ question, index }) => {
         const helpId = `${question.id}-help`;
         const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";
         const helpText = question.helpText
           ? `<p class="help-text" id="${helpId}">${escapeHtml(question.helpText)}</p>`
           : "";

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${index + 1}. ${escapeHtml(question.prompt)}</legend>
               ${helpText}
               <div class="choices">
                 ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
               </div>
             </fieldset>
           </div>
         `;
       };

       const QuizApp = ({ questions }) => `
         <section class="quiz-shell" aria-labelledby="quiz-title">
           <header class="hero">
             <p class="eyebrow">Multiple-answer quiz</p>
             <h1 id="quiz-title">Computer Languages Quiz</h1>
             <p class="intro">Choose all answers that apply for each question, then submit your quiz to see your score.</p>
           </header>
           <form id="quiz-form" novalidate>
             ${questions.map((question, index) => QuestionGroup({ question, index })).join("")}
             <div class="actions">
               <button type="submit">Submit quiz</button>
               <p class="result" id="quiz-result" aria-live="polite"></p>
             </div>
           </form>
         </section>
       `;

       const getSelectedValues = (form, questionId) =>
         Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`)).map(
           (input) => input.value
         );

       const arraysMatch = (selected, correct) =>
         selected.length === correct.length && correct.every((value) => selected.includes(value));

       const renderQuiz = () => {
         const app = document.querySelector("#app");
         app.innerHTML = QuizApp({ questions: quizData });

         const form = document.querySelector("#quiz-form");
         const result = document.querySelector("#quiz-result");

         form.addEventListener("submit", (event) => {
           event.preventDefault();

           const score = quizData.reduce((total, question) => {
             const selected = getSelectedValues(form, question.id);
             const correct = question.choices
               .filter((choice) => choice.correct)
               .map((choice) => choice.id);

             return total + (arraysMatch(selected, correct) ? 1 : 0);
           }, 0);

           result.textContent = `You scored ${score} out of ${quizData.length}.`;
         });
       };

       renderQuiz();
     </script>
   </body>
 </html>

