const axePath = require.resolve("axe-core/axe.min.js");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  await page.setContent(html, { waitUntil: "load" });
  await page.waitForSelector("#quiz-form");
  await page.addScriptTag({ path: axePath });

  const results = await page.evaluate(async () => {
    return window.axe.run(document, {
      resultTypes: ["violations"],
      runOnly: {
        type: "tag",
        values: ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa", "best-practice"]
      }
    });
  });

  await browser.close();

  const wcag = results.violations.filter((violation) => !violation.tags.includes("best-practice"));
  const bestPractice = results.violations.filter((violation) => violation.tags.includes("best-practice"));
  const summary = {
    wcag: wcag.map((violation) => ({
      id: violation.id,
      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target)
    })),
    bestPractice: bestPractice.map((violation) => ({
      id: violation.id,
      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target)
    }))
  };

  console.log(JSON.stringify(summary, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
